async function main(ctx) {
  const input = ctx.input || {};
  const messageId = input.messageId;
  const headers = input.headers;

  // Build the args object for Gmail API
  const args = {
    id: messageId,
    format: 'metadata'
  };

  // If specific headers are requested, join them as comma-separated string
  if (headers && Array.isArray(headers) && headers.length > 0) {
    args.metadataHeaders = headers.join(',');
  }

  return args;
}
